import React, { useState } from 'react';

const TodoList = () => {
  const [taskList, setTaskList] = useState([
    { id: 1, itemName: 'Laptop', qty: 1 },
    { id: 2, itemName: 'Notebook', qty: 2 },
    { id: 3, itemName: 'Pen', qty: 1 }
  ]);

  const addTask = (itemName) => {
    if (!itemName.trim()) return;
    const newTask = {
      id: Date.now(),
      itemName,
      qty: 1
    };
    setTaskList(prev => [...prev, newTask]);
  };

  const deleteTask = (id) => {
    setTaskList(prev => prev.filter(item => item.id !== id));
  };

  return (
    <div>
      <Form addTask={addTask} taskList={taskList} deleteTask={deleteTask} />
    </div>
  );
};

export default TodoList;

function Form({ addTask, taskList, deleteTask }) {
  const [input, setInput] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    addTask(input);
    setInput('');
  };

  return (
    <div>
      <form
        className='container mt-5 p-3 border border-2 rounded bg-warning-subtle'
        onSubmit={handleSubmit}
      >
        <section className="mb-3">
          <h2 className="form-label text-center">
            <span className='badge bg-success m-2'>Required Items to bring</span>
          </h2>
          <input
            type="text"
            className="form-control"
            placeholder='Enter Items '
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
        </section>
        <input type='submit' className="btn btn-sm btn-warning text-dark" />
        <TaskList taskList={taskList} deleteTask={deleteTask} />
      </form>
    </div>
  );
}

function TaskList({ taskList, deleteTask }) {
  return (
  
    <ul className='list-group mt-3'>
      {taskList.map((item) => (
        <Task key={item.id} item={item} deleteTask={deleteTask} />
      ))}
    </ul>
  );
}

function Task({ item, deleteTask }) {
  const { itemName, qty, id } = item;
  return (
    <li className='list-group-item d-flex justify-content-between align-items-center'>
      <span className='text-monospace fs-5'>
        {itemName}
        <span className='badge bg-primary rounded-pill ms-2'>{qty}</span>
      </span>
      <button
        className='btn btn-danger btn-sm'
        onClick={() => deleteTask(id)}
      >
        Delete
      </button>
    </li>
  );
}
